"""Particle-filter controller for the line (pure Python)."""
import math, random

SQ2 = math.sqrt(2.0)


def pdef(m, s):
    """Probability a part is outside -10..10."""
    return 0.5 * (math.erfc((10.0 - m) / (s * SQ2)) + math.erfc((10.0 + m) / (s * SQ2)))


def lot_loss(p):
    """Loss relative to perfect lot under best disposition (ship vs sort)."""
    return min(3000.0 * p, 35.0 + 100.0 * p)


class Controller:
    def __init__(self, n=3000, seed=1, cfg=None):
        self.rng = random.Random(seed)
        self.n = n
        self.cfg = dict(base=2, first=5, maxn=8, lo=0.25, hi=6.0, u=1.0, overhead=4.0,
                        margin=0.0, horizon=2)
        if cfg:
            self.cfg.update(cfg)
        r = self.rng
        # particle: [m, d0, dg, g]
        self.P = [[r.gauss(0, 3.0), r.uniform(0.05, 0.20), r.uniform(0.002, 0.008),
                   r.uniform(0.02, 0.05)] for _ in range(n)]
        self.W = [1.0 / n] * n
        self.age = 0
        self.hist = {}   # slot -> (list of m per particle, age)

    # ---------- filter ----------
    def _norm(self):
        t = sum(self.W)
        if t <= 0 or t != t:
            self.W = [1.0 / self.n] * self.n
        else:
            self.W = [w / t for w in self.W]

    def _maybe_resample(self):
        ess = 1.0 / sum(w * w for w in self.W)
        if ess > self.n * 0.5:
            return
        r = self.rng
        n = self.n
        # systematic resampling
        idx = []
        u = r.random() / n
        c = self.W[0]
        i = 0
        for k in range(n):
            t = u + k / n
            while t > c and i < n - 1:
                i += 1
                c += self.W[i]
            idx.append(i)
        newP = []
        for i in idx:
            m, d0, dg, g = self.P[i]
            d0 = min(0.20, max(0.05, d0 + r.gauss(0, 0.004)))
            dg = min(0.008, max(0.002, dg + r.gauss(0, 0.00015)))
            g = min(0.05, max(0.02, g + r.gauss(0, 0.0008)))
            newP.append([m, d0, dg, g])
        self.P = newP
        for s in list(self.hist):
            ms, a = self.hist[s]
            self.hist[s] = ([ms[i] for i in idx], a)
        self.W = [1.0 / n] * n

    def obs_readings(self, ys):
        a = self.age
        for j, p in enumerate(self.P):
            m = p[0]
            v = (2.0 + p[3] * a) ** 2 + 1.0
            ll = 0.0
            for y in ys:
                ll += -0.5 * (y - m) ** 2 / v
            ll -= 0.5 * len(ys) * math.log(v)
            self.W[j] *= math.exp(max(ll, -700))
        self._norm()
        self._maybe_resample()

    def _obs_count(self, k, ms, a, n=100):
        for j, p in enumerate(self.P):
            q = pdef(ms[j], 2.0 + p[3] * a)
            q = min(max(q, 1e-9), 1 - 1e-9)
            ll = k * math.log(q) + (n - k) * math.log(1 - q)
            self.W[j] *= math.exp(max(ll, -700))
        self._norm()

    def obs_sort(self, k):
        self._obs_count(k, [p[0] for p in self.P], self.age)
        self._maybe_resample()

    def obs_return(self, slot, k):
        if slot in self.hist:
            ms, a = self.hist.pop(slot)
            self._obs_count(k, ms, a)
            self._maybe_resample()

    def record_ship(self, slot):
        self.hist[slot] = ([p[0] for p in self.P], self.age)

    def advance(self, adjust=0.0, replace=False):
        r = self.rng
        if replace:
            for p in self.P:
                p[0] = r.gauss(0, 3.0)
            self.age = 0
            return
        a = self.age
        for p in self.P:
            m = p[0] + p[1] + p[2] * a + r.gauss(0, 0.3)
            if adjust:
                m += adjust * (1.0 + r.gauss(0, 0.05))
            if r.random() < 0.05:
                m += r.gauss(0, 4.0)
            p[0] = m
        self.age += 1

    # ---------- summaries ----------
    def exp_defects(self):
        a = self.age
        return 100.0 * sum(w * pdef(p[0], 2.0 + p[3] * a) for w, p in zip(self.W, self.P))

    def mean_est(self):
        m = sum(w * p[0] for w, p in zip(self.W, self.P))
        v = sum(w * (p[0] - m) ** 2 for w, p in zip(self.W, self.P))
        return m, math.sqrt(v)

    def params(self):
        return [sum(w * p[i] for w, p in zip(self.W, self.P)) for i in (1, 2, 3)]

    # ---------- decisions ----------
    def n_inspect_first(self, budget, slots_left):
        c = self.cfg
        if budget <= 0:
            return 0
        if self.age == 0:
            return min(budget, c['first'])
        per = budget / max(1, slots_left)
        base = c['base']
        if per < base:
            base = int(per) if self.rng.random() > per - int(per) else int(per) + 1
        return min(budget, base)

    def want_more(self, done, budget, slots_left):
        c = self.cfg
        if done >= c['maxn'] or budget < 2:
            return 0
        ed = self.exp_defects()
        if not (c['lo'] < ed < c['hi']):
            return 0
        # keep a reserve for the baseline of the remaining slots
        if budget - 2 < (slots_left - 1) * min(c['base'], 1.5):
            return 0
        return 2

    def disposition(self):
        ed = self.exp_defects()
        return ('ship' if 29.0 * ed < 35.0 else 'sort'), ed

    def choose_adjust(self):
        """Pick D minimising expected loss over the next `horizon` lots."""
        r = self.rng
        k = 250
        sub = r.choices(self.P, weights=self.W, k=k)
        a = self.age
        H = self.cfg['horizon']
        pre = []
        for p in sub:
            m = p[0]
            row = []
            for h in range(1, H + 1):
                m += p[1] + p[2] * (a + h - 1)
                row.append((m, 2.0 + p[3] * (a + h)))
            pre.append(row)

        def cost(D):
            t = 0.0
            for row in pre:
                for m, s in row:
                    t += lot_loss(pdef(m + D, s))
            return t / k + (5.0 if D else 0.0)

        best, bc = 0.0, cost(0.0)
        c0 = bc
        D = -10.0
        while D <= 10.0001:
            if abs(D) > 1e-9:
                cc = cost(D)
                if cc < bc - 1e-9:
                    best, bc = D, cc
            D += 0.25
        if c0 - bc < 0.5:
            return 0.0
        return round(best, 2)

    def lot_value(self, a, g):
        s = math.sqrt((2.0 + g * a) ** 2 + self.cfg['u'] ** 2)
        p = pdef(0.0, s)
        return 100.0 - lot_loss(p) - self.cfg['overhead']

    def should_replace(self, slot, total=120):
        """DP on tool age with posterior-mean spread growth. slot = current slot."""
        g = self.params()[2]
        T = total
        # V[t][a]: value from slot t (lot available, age a) to the end
        V = [[0.0] * (T + 3) for _ in range(T + 3)]
        for t in range(T, slot - 1, -1):
            for a in range(0, T + 1):
                cont = V[t + 1][min(a + 1, T)]
                rep = -300.0 - 10.0 + (V[t + 2][0] if t + 2 <= T else 0.0)
                V[t][a] = self.lot_value(a, g) + max(cont, rep)
        a = self.age
        cont = V[slot + 1][min(a + 1, T)]
        rep = -300.0 - 10.0 + (V[slot + 2][0] if slot + 2 <= T else 0.0)
        return rep > cont + self.cfg['margin'], rep - cont

