        return 100.0 - lot_loss(p) - self.cfg['overhead']

    def should_replace(self, slot, total=120):
        """DP on tool age with posterior-mean spread growth. slot = current slot."""
        g = self.params()[2]
        T = total
        # V[t][a]: value from slot t (lot available, age a) to the end
        V = [[0.0] * (T + 3) for _ in range(T + 3)]
        for t in range(T, slot - 1, -1):
            for a in range(0, T + 1):
                cont = V[t + 1][min(a + 1, T)]
                rep = -300.0 - 10.0 + (V[t + 2][0] if t + 2 <= T else 0.0)
                V[t][a] = self.lot_value(a, g) + max(cont, rep)
        a = self.age
        cont = V[slot + 1][min(a + 1, T)]
        rep = -300.0 - 10.0 + (V[slot + 2][0] if slot + 2 <= T else 0.0)
        return rep > cont + self.cfg['margin'], rep - cont
